// zaehlt die Edelsteine im Stapel s; s soll danach unveraendert sein
public static int zaehle(Stack s) {
    int anzahl = 0;
    Queue hilf = new Queue();
    while (!s.isEmpty()) {
        hilf.enqueue(s.pop());
        anzahl = anzahl + 1;
    }
    while (!hilf.isEmpty()) {
        s.push(hilf.dequeue());
    }
    return anzahl;
}

