public static int binaer(int[] r, int x) {
    int lo = 0;
    int hi = r.length - 1;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        if (r[mid] == x) {
            return mid;
        }
        if (r[mid] < x) {
            lo = mid + 1;
        } else {
            hi = mid - 1;
        }
    }
    return -1;
}

public static int zerlege(int n) {
    if (n < 3) {
        return n;
    }
    return zerlege(n / 3) + n % 3;
}

