public static boolean suche(BinTree b, int x) {
    int wert = (Integer) b.getItem();
    if (x == wert) {
        return true;
    }
    if (x < wert) {
        return suche(b.getLeft(), x);
    }
    return suche(b.getRight(), x);
}

public static int summe(Queue q) {
    int s = 0;
    Queue hilf = new Queue();
    while (!q.isEmpty()) {
        int x = (Integer) q.dequeue();
        s = s + x;
        hilf.enqueue(x);
    }
    while (!hilf.isEmpty()) {
        q.enqueue(hilf.dequeue());
    }
    return s;
}

// Name des naechsten Gegners in der Welle; "" wenn die Welle leer ist
