    String name = (String) welle.dequeue();
    if (welle.isEmpty()) {
        return "";
    }
    return name;
}

// liefert das groesste Gold in q; q soll unveraendert bleiben
public static int maxGold(Queue q) {
    int max = -1;
    int n = 0;
    Queue hilf = new Queue();
    while (!q.isEmpty()) {
        int x = (Integer) q.dequeue();
        if (x > max) {
            max = x;
        }
        hilf.enqueue(x);
        n = n + 1;
    }
    for (int i = 0; i < n - 1; i++) {
        q.enqueue(hilf.dequeue());
    }
    return max;
}

public static String runen(int n) {
    if (n <= 0) {
        return "";
    }
    if (n % 2 == 0) {
        return runen(n - 2) + "#";
    }
    return "*" + runen(n - 1);
}

